def check_card_number(number):
    """Check a card number with the Luhn checksum."""
    if not isinstance(number, str):
        raise TypeError('card number must be a string')
    if not number.isdigit():
        return False
    if len(number) < 12 or len(number) > 19:
        return False
    total = 0
    for index, ch in enumerate(reversed(number)):
        digit = int(ch)
        if index % 2 == 1:
            digit = digit * 2
            if digit > 9:
                digit = digit - 9
        total = total + digit
    return total % 10 == 0

